// Production static host for Sharawla Staff 10.5.14.
// Public PWA assets only. The Supabase key below is publishable, not service-role.
const TEXT_ASSETS:Record<string,{type:string,body:string}>={"index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n <meta charset=\"utf-8\">\n <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover,user-scalable=no\">\n <meta name=\"theme-color\" content=\"#0b3b35\">\n <meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n <meta name=\"apple-mobile-web-app-status-bar-style\" content=\"black-translucent\">\n <meta name=\"apple-mobile-web-app-title\" content=\"Sharawla Staff\">\n <title>Sharawla Staff</title>\n <link rel=\"manifest\" href=\"manifest.webmanifest\">\n <link rel=\"apple-touch-icon\" sizes=\"192x192\" href=\"icon-192.png\">\n <link rel=\"stylesheet\" href=\"styles.css?v=10.5.14\">\n</head>\n<body>\n <div id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n <main id=\"shell\">\n  <header class=\"topbar\">\n   <div class=\"brand\"><img src=\"icon.svg\" alt=\"\"><div><strong>Sharawla Staff</strong><small id=\"employeeName\">تطبيق الموظفين</small></div></div>\n   <div class=\"status\"><span id=\"networkDot\"></span><span id=\"networkText\">متصل</span></div>\n  </header>\n\n  <section id=\"setupView\" class=\"view auth-view hidden\">\n   <div class=\"auth-card\"><h1>ربط تطبيق الموظفين</h1><p>أدخل إعداد الاتصال التي يوفرها مدير Sharawla. المفتاح المطلوب Publishable فقط.</p>\n    <form id=\"setupForm\"><label>Supabase Project URL<input id=\"backendUrl\" inputmode=\"url\" placeholder=\"https://xxxx.supabase.co\" required></label><label>Publishable key<textarea id=\"backendKey\" rows=\"3\" required></textarea></label><button class=\"primary\" type=\"submit\">حفظ الاتصال</button></form>\n   </div>\n  </section>\n\n  <section id=\"loginView\" class=\"view auth-view hidden\">\n   <div class=\"auth-card\"><img class=\"hero-icon\" src=\"icon.svg\" alt=\"\"><h1>دخول الموظف</h1><p>استخدم كود الموظف أو رقم الموبايل والـPIN المؤقت.</p>\n    <form id=\"loginForm\"><label>كود الموظف أو الموبايل<input id=\"identity\" autocomplete=\"username\" required></label><label>PIN من 6 أرقام<input id=\"pin\" type=\"password\" inputmode=\"numeric\" pattern=\"[0-9]{6}\" maxlength=\"6\" autocomplete=\"current-password\" required></label><button class=\"primary\" type=\"submit\">دخول</button></form>\n    <button id=\"changeConnection\" class=\"link-btn\" type=\"button\">تغيير إعداد الاتصال</button>\n   </div>\n  </section>\n\n  <section id=\"pinView\" class=\"view auth-view hidden\">\n   <div class=\"auth-card\"><h1>تغيير PIN لأول مرة</h1><p>اختر PIN جديدًا من 6 أرقام. ستسجّل الدخول مجددًا بعد التغيير.</p>\n    <form id=\"pinForm\"><label>PIN الحالي<input id=\"currentPin\" type=\"password\" inputmode=\"numeric\" maxlength=\"6\" required></label><label>PIN الجديد<input id=\"newPin\" type=\"password\" inputmode=\"numeric\" maxlength=\"6\" required></label><label>تأكيد PIN<input id=\"confirmPin\" type=\"password\" inputmode=\"numeric\" maxlength=\"6\" required></label><button class=\"primary\" type=\"submit\">حفظ PIN</button></form>\n   </div>\n  </section>\n\n  <section id=\"appView\" class=\"view hidden\">\n   <div id=\"offlineBanner\" class=\"offline-banner hidden\">أنت غير متصل — الحركات ستُحفظ على الجهاز</div>\n   <div id=\"page\" class=\"page\"></div>\n   <nav class=\"bottom-nav\" aria-label=\"التنقل\">\n    <button data-page=\"home\" class=\"active\"><span>⌂</span>الرئيسية</button>\n    <button data-page=\"history\"><span>◷</span>الحضور</button>\n    <button data-page=\"schedule\"><span>▦</span>الجدول</button>\n    <button data-page=\"summary\"><span>≡</span>ملفي</button>\n    <button data-page=\"sync\"><span>↻</span><b id=\"pendingBadge\" class=\"badge hidden\">0</b>المزامنة</button>\n   </nav>\n  </section>\n </main>\n\n <div id=\"cameraModal\" class=\"camera-modal hidden\" role=\"dialog\" aria-modal=\"true\">\n  <div class=\"camera-card\"><h2 id=\"cameraTitle\">تسجيل الحضور</h2><p>سيلفي مباشر من الكاميرا — لا يوجد اختيار من المعرض.</p><video id=\"cameraVideo\" autoplay playsinline muted></video><canvas id=\"cameraCanvas\" class=\"hidden\"></canvas><div id=\"gpsState\" class=\"gps-state\">سيتم التقاط الموقع عند الضغط.</div><div class=\"camera-actions\"><button id=\"cancelCamera\" type=\"button\">إلغاء</button><button id=\"captureAttendance\" class=\"primary\" type=\"button\">التقاط وتسجيل</button></div></div>\n </div>\n\n <script src=\"hr-staff-domain.js?v=10.5.14\"></script>\n <script src=\"hr-staff-store.js?v=10.5.14\"></script>\n <script src=\"app.js?v=10.5.14\"></script>\n</body>\n</html>\n"},"app.js":{"type":"text/javascript; charset=utf-8","body":"(function(global){\n'use strict';\nconst APP_VERSION='10.5.14-hr2';\nconst $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];\nconst store=global.SharawlaStaffStore,domain=global.SharawlaStaffDomain;\nconst queue=new domain.DurableAttendanceQueue(store.queueStore);\nlet currentSession=store.session(),snapshot=null,currentPage='home',cameraStream=null,pendingType=null,replaying=false;\n\nconst esc=value=>String(value??'').replace(/[&<>'\"]/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;',\"'\":'&#39;','\"':'&quot;'}[ch]));\nconst fmt=value=>value?new Date(value).toLocaleString('ar-EG',{dateStyle:'medium',timeStyle:'short'}):'—';\nconst date=value=>value?new Date(value).toLocaleDateString('ar-EG',{dateStyle:'medium'}):'—';\nconst tx=prefix=>`${prefix}-${Date.now()}-${store.randomId()}`;\nfunction toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4200)}\nfunction show(id){for(const view of $$('.view'))view.classList.add('hidden');$(id).classList.remove('hidden')}\nfunction connection(){return store.config()||global.SHARAWLA_STAFF_CONFIG||null}\nfunction endpoint(){const cfg=connection();if(!cfg?.url||!cfg?.key)throw new Error('إعداد الاتصال غير مكتمل');return `${String(cfg.url).replace(/\\/$/,'')}/functions/v1/hr-staff-api`}\nasync function api(body,{form=false,requireSession=true}={}){\n const cfg=connection(),headers={apikey:cfg.key,Authorization:`Bearer ${cfg.key}`};\n if(requireSession&&currentSession?.session_token)headers['x-staff-session']=currentSession.session_token;\n if(!form)headers['content-type']='application/json';\n const response=await fetch(endpoint(),{method:'POST',headers,body:form?body:JSON.stringify(body),cache:'no-store'});\n const data=await response.json().catch(()=>({ok:false,code:'INVALID_SERVER_RESPONSE'}));\n if(!response.ok||data.ok===false){const error=new Error(data.code||'تعذر تنفيذ الطلب');error.code=data.code;if(data.code==='STAFF_SESSION_INVALID'){store.saveSession(null);currentSession=null}throw error}\n return data;\n}\nfunction cacheSnapshot(value){snapshot=value;localStorage.setItem('sharawlaStaffSnapshotV1',JSON.stringify(value))}\nfunction loadSnapshot(){try{return JSON.parse(localStorage.getItem('sharawlaStaffSnapshotV1')||'null')}catch{return null}}\nasync function refreshSnapshot(){\n if(!currentSession)return;\n if(!navigator.onLine){snapshot=loadSnapshot();render();return}\n const now=new Date(),from=new Date(now);from.setDate(from.getDate()-62);const to=new Date(now);to.setDate(to.getDate()+62);\n try{const result=await api({action:'snapshot',from:from.toISOString().slice(0,10),to:to.toISOString().slice(0,10)});cacheSnapshot(result.data);render()}\n catch(error){snapshot=loadSnapshot();if(!snapshot&&error.code==='STAFF_SESSION_INVALID')bootstrap();else render()}\n}\nfunction updateNetwork(){const offline=!navigator.onLine;$('#networkText').textContent=offline?'غير متصل':'متصل';$('.status').classList.toggle('offline',offline);$('#offlineBanner').classList.toggle('hidden',!offline)}\nasync function updatePending(){const rows=await queue.pending(),badge=$('#pendingBadge');badge.textContent=String(rows.length);badge.classList.toggle('hidden',rows.length===0);return rows}\nasync function reportSyncState(lastError=null){if(!navigator.onLine||!currentSession)return;try{const rows=await queue.pending();await api({action:'sync-state',pending_count:rows.length,last_error:lastError})}catch{}}\nfunction summaryPill(row){if(row.approved_leave)return '<span class=\"pill\">إجازة معتمدة</span>';if(row.absent)return '<span class=\"pill bad\">غياب</span>';if(row.incomplete)return '<span class=\"pill warn\">حركة غير مكتملة</span>';return '<span class=\"pill\">حاضر</span>'}\nfunction renderHome(){\n const employee=snapshot?.employee||currentSession?.employee||{},today=snapshot?.today||{},now=new Date();\n $('#employeeName').textContent=employee.name||'تطبيق الموظفين';\n $('#page').innerHTML=`<section class=\"hero-card\"><div class=\"muted\">مرحبًا، ${esc(employee.name||'')}</div><h1>وردية اليوم</h1><div id=\"liveClock\" class=\"clock\">${now.toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</div><div>${today.work_date?summaryPill(today):'<span class=\"pill warn\">لا يوجد ملخص بعد</span>'}</div><div class=\"attendance-actions\"><button class=\"check-in\" data-attendance=\"check_in\">📷 حضور</button><button class=\"check-out\" data-attendance=\"check_out\">📷 انصراف</button></div></section>\n <div class=\"kpi-grid\"><div class=\"kpi\"><span>وقت الحضور</span><b>${today.actual_check_in_at?new Date(today.actual_check_in_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'}):'—'}</b></div><div class=\"kpi\"><span>وقت الانصراف</span><b>${today.actual_check_out_at?new Date(today.actual_check_out_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'}):'—'}</b></div><div class=\"kpi\"><span>التأخير</span><b>${Number(today.late_minutes||0)} د</b></div><div class=\"kpi\"><span>الإضافي</span><b>${Number(today.overtime_minutes||0)} د</b></div></div>\n <section class=\"card\"><h3>حالة اليوم</h3><div class=\"row\"><span>ساعات العمل</span><b>${(Number(today.worked_minutes||0)/60).toFixed(2)}</b></div><div class=\"row\"><span>خروج مبكر</span><b>${Number(today.early_leave_minutes||0)} دقيقة</b></div><div class=\"row\"><span>مراجعة مطلوبة</span><b>${Number(snapshot?.pending_review||0)}</b></div><div class=\"staff-request-actions\"><button id=\"leaveRequestBtn\" class=\"primary\" type=\"button\">طلب إجازة أو إذن</button><button id=\"advanceRequestBtn\" type=\"button\">طلب سلفة</button></div></section>`;\n $$('#page [data-attendance]').forEach(button=>button.onclick=()=>openCamera(button.dataset.attendance));\n $('#leaveRequestBtn').onclick=openLeaveRequest;\n $('#advanceRequestBtn').onclick=openAdvanceRequest;\n}\nfunction renderHistory(){\n const rows=snapshot?.history||[];\n $('#page').innerHTML=`<h1>سجل الحضور</h1><section class=\"card\">${rows.map(row=>`<div class=\"row\"><div><b>${date(row.work_date)}</b><small class=\"muted\">${fmt(row.actual_check_in_at)} ← ${fmt(row.actual_check_out_at)}</small></div><div>${summaryPill(row)}<small class=\"muted\">${Number(row.worked_minutes||0)} دقيقة</small></div></div>`).join('')||'<p class=\"muted\">لا توجد بيانات محفوظة.</p>'}</section>`;\n}\nfunction renderSchedule(){\n const rows=snapshot?.schedule||[];\n $('#page').innerHTML=`<h1>جدول عملي</h1>${rows.map(row=>`<section class=\"card\"><h3>${esc(row.name)}</h3><div class=\"row\"><span>الموعد</span><b>${esc(String(row.scheduled_start||'').slice(0,5))} — ${esc(String(row.scheduled_end||'').slice(0,5))}${row.overnight?' (ليلي)':''}</b></div><div class=\"row\"><span>السماح</span><b>${Number(row.grace_minutes||0)} دقيقة</b></div><div class=\"row\"><span>الأيام</span><b>${(row.work_days||[]).join('، ')}</b></div><div class=\"muted\">ساري من ${date(row.assignment_from||row.effective_from)} إلى ${row.assignment_to||row.effective_to?date(row.assignment_to||row.effective_to):'مستمر'}</div></section>`).join('')||'<section class=\"card muted\">لا يوجد جدول مسند حاليًا.</section>'}`;\n}\nfunction renderSummary(){\n const rows=snapshot?.history||[],total=key=>rows.reduce((n,row)=>n+Number(row[key]||0),0),absent=rows.filter(r=>r.absent).length,leave=rows.filter(r=>r.approved_leave).length;\n const advances=snapshot?.advance_requests||[],adjustments=snapshot?.adjustments||[],payroll=snapshot?.payroll||[],notes=snapshot?.notifications||[];\n $('#page').innerHTML=`<h1>ملفي وطلباتي</h1><div class=\"kpi-grid\"><div class=\"kpi\"><span>ساعات العمل</span><b>${(total('worked_minutes')/60).toFixed(1)}</b></div><div class=\"kpi\"><span>التأخير</span><b>${total('late_minutes')} د</b></div><div class=\"kpi\"><span>الإضافي</span><b>${total('overtime_minutes')} د</b></div><div class=\"kpi\"><span>الغياب</span><b>${absent}</b></div></div>\n <section class=\"card\"><div class=\"row\"><span>الخروج المبكر</span><b>${total('early_leave_minutes')} دقيقة</b></div><div class=\"row\"><span>الإجازات المعتمدة</span><b>${leave}</b></div><div class=\"row\"><span>حركات ناقصة</span><b>${rows.filter(r=>r.incomplete).length}</b></div></section>\n <section class=\"card\"><div class=\"section-title\"><h3>🔔 الإشعارات</h3><span class=\"pill\">${notes.filter(n=>!n.read_at).length} جديد</span></div>${notes.slice(0,20).map(n=>`<button class=\"self-note ${n.read_at?'':'unread'}\" data-staff-note=\"${n.id}\"><b>${esc(n.title)}</b><span>${esc(n.body||'')}</span><small>${fmt(n.created_at)}</small></button>`).join('')||'<p class=\"muted\">لا توجد إشعارات.</p>'}</section>\n <section class=\"card\"><div class=\"section-title\"><h3>💰 طلبات السلف</h3><button id=\"summaryAdvanceRequest\" type=\"button\">طلب سلفة</button></div>${advances.map(a=>`<div class=\"row\"><div><b>${Number(a.amount||0).toFixed(2)}</b><small class=\"muted\">${esc(a.reason||'بدون سبب')}</small></div><span class=\"pill\">${esc(a.status)}</span></div>`).join('')||'<p class=\"muted\">لا توجد طلبات سلفة.</p>'}</section>\n <section class=\"card\"><h3>➕➖ الجزاءات والمكافآت المعتمدة</h3>${adjustments.slice(0,20).map(a=>`<div class=\"row\"><span>${esc(a.adjustment_type)} — ${esc(a.reason||'')}</span><b>${Number(a.amount||0).toFixed(2)}</b></div>`).join('')||'<p class=\"muted\">لا توجد حركات معتمدة.</p>'}</section>\n <section class=\"card\"><h3>🧾 المرتبات</h3>${payroll.slice(0,12).map(p=>`<div class=\"row\"><div><b>${esc(p.period_start)} → ${esc(p.period_end)}</b><small class=\"muted\">${esc(p.status)}</small></div><b>${Number(p.net_amount||0).toFixed(2)}</b></div>`).join('')||'<p class=\"muted\">لا توجد مسيرات مرتبات.</p>'}</section>\n <section class=\"card\"><button id=\"logoutBtn\" class=\"primary\" type=\"button\">تسجيل الخروج</button></section>`;\n $('#logoutBtn').onclick=logout;$('#summaryAdvanceRequest').onclick=openAdvanceRequest;\n $$('#page [data-staff-note]').forEach(b=>b.onclick=async()=>{try{await api({action:'notification-read',notification_id:Number(b.dataset.staffNote)});await refreshSnapshot()}catch(error){toast(error.message||'تعذر تحديث الإشعار')}});\n}\nasync function renderSync(){\n const rows=await updatePending();\n $('#page').innerHTML=`<h1>المزامنة</h1><section class=\"card\"><div class=\"row\"><span>الحركات المنتظرة</span><b>${rows.length}</b></div><button id=\"syncNow\" class=\"primary\" type=\"button\" ${!navigator.onLine||replaying?'disabled':''}>مزامنة الآن</button></section>${rows.map(row=>`<section class=\"card sync-item\"><b>${row.eventType==='check_in'?'حضور':'انصراف'}</b><div>${fmt(row.capturedAtDevice)}</div><div class=\"muted\">المحاولات: ${row.attempts||0} — ${esc(row.state)}</div>${row.lastError?`<div class=\"danger\">${esc(row.lastError)}</div>`:''}</section>`).join('')}`;\n $('#syncNow')?.addEventListener('click',replayPending);\n}\nfunction render(){\n if(!currentSession)return bootstrap();\n show('#appView');$$('.bottom-nav button').forEach(button=>button.classList.toggle('active',button.dataset.page===currentPage));\n if(currentPage==='home')renderHome();else if(currentPage==='history')renderHistory();else if(currentPage==='schedule')renderSchedule();else if(currentPage==='summary')renderSummary();else renderSync();\n updatePending();updateNetwork();\n}\nfunction geolocate(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(new Error('الموقع غير مدعوم'));navigator.geolocation.getCurrentPosition(position=>resolve({latitude:position.coords.latitude,longitude:position.coords.longitude,accuracyM:position.coords.accuracy,capturedAt:new Date(position.timestamp).toISOString()}),()=>reject(new Error('تعذر التقاط GPS. اسمح بالوصول للموقع وحاول مجددًا.')),{enableHighAccuracy:true,timeout:20000,maximumAge:0})})}\nfunction stopCamera(){cameraStream?.getTracks().forEach(track=>track.stop());cameraStream=null;$('#cameraModal').classList.add('hidden')}\nasync function openCamera(type){\n pendingType=type;$('#cameraTitle').textContent=type==='check_in'?'تسجيل الحضور':'تسجيل الانصراف';$('#gpsState').textContent='سيتم التقاط الموقع عند الضغط.';$('#cameraModal').classList.remove('hidden');\n try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:1280},height:{ideal:1280}},audio:false});$('#cameraVideo').srcObject=cameraStream}\n catch{stopCamera();toast('تعذر فتح الكاميرا. امنح إذن الكاميرا واستخدم HTTPS.');}\n}\nfunction cameraBlob(){return new Promise((resolve,reject)=>{const video=$('#cameraVideo'),canvas=$('#cameraCanvas'),width=Math.min(960,video.videoWidth||720),height=Math.round(width*(video.videoHeight||720)/(video.videoWidth||720));canvas.width=width;canvas.height=height;const context=canvas.getContext('2d');context.translate(width,0);context.scale(-1,1);context.drawImage(video,0,0,width,height);canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('تعذر إنشاء السيلفي')),'image/jpeg',.84)})}\nasync function captureAttendance(){\n const button=$('#captureAttendance');button.disabled=true;\n try{\n  $('#gpsState').textContent='جاري التقاط GPS والسيلفي…';const capturedAt=new Date().toISOString();const [gps,selfie]=await Promise.all([geolocate(),cameraBlob()]);\n  const clientTxId=tx('HR-ATT'),offline=!navigator.onLine,envelope={clientTxId,eventType:pendingType,capturedAtDevice:capturedAt,gps,selfie,capturedOffline:offline,branchId:Number(currentSession.employee?.branch_id),deviceId:store.deviceId(),appVersion:APP_VERSION,deviceTimeOffsetMinutes:new Date().getTimezoneOffset()};\n  await queue.enqueue(envelope);stopCamera();toast('تم تسجيل الحركة محليًا - في انتظار المزامنة');await updatePending();render();\n  if(navigator.onLine)await replayPending();\n }catch(error){toast(error.message||String(error))}finally{button.disabled=false}\n}\nasync function sendEnvelope(row){\n const form=new FormData();form.set('action','selfie-upload');form.set('client_tx_id',row.clientTxId);form.set('captured_at_device',row.capturedAtDevice);form.set('selfie',row.selfie,`${row.clientTxId}.jpg`);\n const upload=await api(form,{form:true});\n const payload={employee_id:Number(currentSession.employee.id),branch_id:row.branchId,event_type:row.eventType,client_tx_id:row.clientTxId,captured_at_device:row.capturedAtDevice,latitude:row.gps.latitude,longitude:row.gps.longitude,accuracy_m:row.gps.accuracyM,selfie_storage_reference:upload.selfie.reference,device_id:row.deviceId,captured_offline:row.capturedOffline,app_version:row.appVersion,device_time_offset_minutes:row.deviceTimeOffsetMinutes,metadata:{queue_created_at:row.createdAt,gps_timestamp:row.gps.capturedAt}};\n return (await api({action:'attendance',payload})).ack;\n}\nasync function replayPending(){\n if(replaying||!navigator.onLine||!currentSession)return;replaying=true;\n try{const result=await queue.replay(sendEnvelope);if(result.synced)toast(`تمت مزامنة ${result.synced} حركة`);await updatePending();await reportSyncState();await refreshSnapshot()}\n catch(error){await reportSyncState(error.message||String(error));toast(error.message||'تعذر المزامنة')}finally{replaying=false;if(currentPage==='sync')renderSync()}\n}\nasync function login(event){\n event.preventDefault();const button=event.submitter;button.disabled=true;\n try{const result=await api({action:'login',identity:$('#identity').value.trim(),pin:$('#pin').value,device_uid:store.deviceId(),device_name:'Sharawla Staff PWA',device_model:navigator.userAgentData?.platform||'',platform:navigator.platform||''},{requireSession:false});currentSession={session_token:result.session_token,expires_at:result.expires_at,must_change_pin:result.must_change_pin,employee:result.employee,device_id:result.device_id};store.saveSession(currentSession);if(result.must_change_pin){show('#pinView');$('#currentPin').focus()}else{await enterApp()}}\n catch(error){toast(error.message||'تعذر تسجيل الدخول')}finally{button.disabled=false}\n}\nasync function changePin(event){event.preventDefault();const next=$('#newPin').value;if(!/^\\d{6}$/.test(next)||next!==$('#confirmPin').value)return toast('تأكيد PIN غير مطابق أو ليس 6 أرقام');try{await api({action:'change-pin',current_pin:$('#currentPin').value,new_pin:next});store.saveSession(null);currentSession=null;toast('تم تغيير PIN. سجل الدخول بالرقم الجديد.');bootstrap()}catch(error){toast(error.message||'تعذر تغيير PIN')}}\nasync function logout(){try{if(navigator.onLine)await api({action:'logout'})}catch{}store.saveSession(null);currentSession=null;snapshot=null;bootstrap()}\nfunction openAdvanceRequest(){\n const wrapper=document.createElement('div');wrapper.className='camera-modal';wrapper.innerHTML=`<form class=\"camera-card\"><h2>طلب سلفة</h2><label>المبلغ<input data-f=\"amount\" type=\"number\" min=\"1\" step=\".01\" required></label><label>طريقة الاستقطاع<select data-f=\"mode\"><option value=\"one_time\">مرة واحدة</option><option value=\"installments\">أقساط</option></select></label><label>قيمة القسط<input data-f=\"installment\" type=\"number\" min=\"1\" step=\".01\"></label><label>عدد الأقساط<input data-f=\"count\" type=\"number\" min=\"1\" step=\"1\"></label><label>السبب<textarea data-f=\"reason\" rows=\"3\"></textarea></label><div class=\"camera-actions\"><button type=\"button\" data-close>إلغاء</button><button class=\"primary\" type=\"submit\">إرسال إلى HR</button></div></form>`;document.body.appendChild(wrapper);\n wrapper.querySelector('[data-close]').onclick=()=>wrapper.remove();\n wrapper.querySelector('form').onsubmit=async event=>{event.preventDefault();if(!navigator.onLine)return toast('إرسال طلب السلفة يحتاج اتصالًا بالإنترنت.');const value=name=>wrapper.querySelector(`[data-f=\"${name}\"]`).value,mode=value('mode');try{await api({action:'advance-request',amount:Number(value('amount')),repayment_mode:mode,installment_amount:mode==='installments'?Number(value('installment')):null,installments_count:mode==='installments'?Number(value('count')):null,reason:value('reason'),client_tx_id:tx('HR-ADV')});wrapper.remove();toast('تم إرسال طلب السلفة إلى HR');await refreshSnapshot()}catch(error){toast(error.message||'تعذر إرسال طلب السلفة')}};\n}\nfunction openLeaveRequest(){\n const wrapper=document.createElement('div');wrapper.className='camera-modal';wrapper.innerHTML=`<form class=\"camera-card\"><h2>طلب إجازة أو إذن</h2><label>النوع<select data-f=\"type\"><option value=\"leave\">إجازة</option><option value=\"permission\">إذن قصير</option><option value=\"late_permission\">إذن تأخير</option><option value=\"early_leave_permission\">إذن خروج مبكر</option><option value=\"sick_leave\">إجازة مرضية</option><option value=\"unpaid_leave\">إجازة بدون مرتب</option></select></label><label>من<input data-f=\"from\" type=\"datetime-local\" required></label><label>إلى<input data-f=\"to\" type=\"datetime-local\" required></label><label>السبب<textarea data-f=\"reason\" rows=\"3\"></textarea></label><div class=\"camera-actions\"><button type=\"button\" data-close>إلغاء</button><button class=\"primary\" type=\"submit\">إرسال</button></div></form>`;document.body.appendChild(wrapper);wrapper.querySelector('[data-close]').onclick=()=>wrapper.remove();wrapper.querySelector('form').onsubmit=async event=>{event.preventDefault();if(!navigator.onLine)return toast('إرسال طلب الإجازة يحتاج اتصالًا بالإنترنت.');const value=name=>wrapper.querySelector(`[data-f=\"${name}\"]`).value;try{await api({action:'leave-request',request_type:value('type'),starts_at:new Date(value('from')).toISOString(),ends_at:new Date(value('to')).toISOString(),reason:value('reason'),client_tx_id:tx('HR-LEAVE')});wrapper.remove();toast('تم إرسال الطلب للمدير');await refreshSnapshot()}catch(error){toast(error.message||'تعذر إرسال الطلب')}};\n}\nasync function enterApp(){currentPage='home';snapshot=loadSnapshot();render();await replayPending();await refreshSnapshot()}\nfunction bootstrap(){\n updateNetwork();const cfg=connection();if(!cfg?.url||!cfg?.key)return show('#setupView');\n currentSession=store.session();if(!currentSession)return show('#loginView');\n if(currentSession.must_change_pin)return show('#pinView');enterApp();\n}\n\n$('#setupForm').addEventListener('submit',event=>{event.preventDefault();const url=$('#backendUrl').value.trim().replace(/\\/$/,'') ,key=$('#backendKey').value.trim();if(!/^https:\\/\\/[a-z0-9-]+\\.supabase\\.co$/i.test(url)||!key.startsWith('sb_'))return toast('راجع Project URL وPublishable key');store.saveConfig({url,key});bootstrap()});\n$('#changeConnection').onclick=()=>{store.saveSession(null);localStorage.removeItem('sharawlaStaffConfigV1');currentSession=null;bootstrap()};\n$('#loginForm').addEventListener('submit',login);$('#pinForm').addEventListener('submit',changePin);\n$('.bottom-nav').addEventListener('click',event=>{const button=event.target.closest('[data-page]');if(!button)return;currentPage=button.dataset.page;render()});\n$('#cancelCamera').onclick=stopCamera;$('#captureAttendance').onclick=captureAttendance;\naddEventListener('online',()=>{updateNetwork();replayPending()});addEventListener('offline',updateNetwork);addEventListener('focus',replayPending);addEventListener('pageshow',replayPending);\ndocument.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')replayPending()});\nsetInterval(()=>{if(currentPage==='home')$('#liveClock')?.replaceChildren(document.createTextNode(new Date().toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})))},30000);\nsetInterval(()=>{if(document.visibilityState==='visible')replayPending()},60000);\nif('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(reg=>{navigator.serviceWorker.addEventListener('message',event=>{if(event.data?.type==='REPLAY_PENDING')replayPending()});if('sync'in reg)reg.sync.register('sharawla-staff-replay').catch(()=>{})}).catch(()=>{});\nbootstrap();\n})(globalThis);\n"},"hr-staff-domain.js":{"type":"text/javascript; charset=utf-8","body":"(function(root,factory){\n const api=factory();\n if(typeof module==='object'&&module.exports)module.exports=api;\n else root.SharawlaStaffDomain=Object.freeze(api);\n})(typeof globalThis!=='undefined'?globalThis:this,function(){\n'use strict';\n\nconst validStatuses=new Set(['verified','verified_after_sync']);\nconst minutes=ms=>Math.max(0,Math.floor(ms/60000));\nconst round2=n=>Math.round((Number(n)+Number.EPSILON)*100)/100;\n\nfunction stable(value){\n if(Array.isArray(value))return value.map(stable);\n if(value&&typeof value==='object')return Object.keys(value).sort().reduce((out,key)=>{if(value[key]!==undefined)out[key]=stable(value[key]);return out},{});\n return value;\n}\nfunction canonicalPayload(value){return JSON.stringify(stable(value))}\n\nfunction haversineMeters(a,b){\n const rad=n=>Number(n)*Math.PI/180,R=6371000;\n const dLat=rad(b.latitude-a.latitude),dLon=rad(b.longitude-a.longitude);\n const q=Math.sin(dLat/2)**2+Math.cos(rad(a.latitude))*Math.cos(rad(b.latitude))*Math.sin(dLon/2)**2;\n return round2(R*2*Math.atan2(Math.sqrt(q),Math.sqrt(1-q)));\n}\n\nfunction verifyGeofence({point,geofence,outsidePolicy='pending_review',poorAccuracyPolicy='pending_review',offline=false}){\n const distance=haversineMeters(geofence,point);\n let status=offline?'verified_after_sync':'verified',reason=null;\n if(Number.isFinite(Number(geofence.minimumAccuracyM))&&Number(point.accuracyM)>Number(geofence.minimumAccuracyM)){\n  status=poorAccuracyPolicy==='reject'?'rejected':'pending_review';reason='poor_gps_accuracy';\n }else if(distance>Number(geofence.allowedRadiusM)){\n  status=outsidePolicy==='reject'?'rejected':'pending_review';reason='outside_geofence';\n }\n return {distanceFromBranchM:distance,verificationStatus:status,verificationReason:reason};\n}\n\nfunction calculateDailySummary({schedule,events=[],approvedLeave=false,adjustment=null}){\n const start=new Date(schedule.startAt),end=new Date(schedule.endAt);\n if(!(start<end))throw new Error('INVALID_SCHEDULE_WINDOW');\n const accepted=events.filter(e=>validStatuses.has(e.verificationStatus)).sort((a,b)=>new Date(a.capturedAt)-new Date(b.capturedAt));\n let checkIn=accepted.find(e=>e.type==='check_in')?.capturedAt||null;\n let checkOut=[...accepted].reverse().find(e=>e.type==='check_out')?.capturedAt||null;\n if(adjustment?.actualCheckInAt!==undefined)checkIn=adjustment.actualCheckInAt;\n if(adjustment?.actualCheckOutAt!==undefined)checkOut=adjustment.actualCheckOutAt;\n const inAt=checkIn?new Date(checkIn):null,outAt=checkOut?new Date(checkOut):null;\n let result={\n  scheduledStartAt:start.toISOString(),scheduledEndAt:end.toISOString(),actualCheckInAt:inAt?.toISOString()||null,\n  actualCheckOutAt:outAt?.toISOString()||null,workedMinutes:0,breakMinutes:Number(schedule.breakMinutes||0),lateMinutes:0,\n  earlyLeaveMinutes:0,overtimeMinutes:0,absent:!inAt&&!approvedLeave,incomplete:Boolean((inAt&&!outAt)||(!inAt&&outAt)),\n  missingCheckOut:Boolean(inAt&&!outAt),approvedLeave:Boolean(approvedLeave)\n };\n if(inAt)result.lateMinutes=Math.max(0,minutes(inAt-start)-Number(schedule.graceMinutes||0));\n if(outAt){\n  result.earlyLeaveMinutes=Math.max(0,minutes(end-outAt)-Number(schedule.earlyLeaveGraceMinutes||0));\n  result.overtimeMinutes=Math.max(0,minutes(outAt-end)-Number(schedule.overtimeAfterMinutes||0));\n }\n if(inAt&&outAt&&outAt>inAt)result.workedMinutes=Math.max(0,minutes(outAt-inAt)-result.breakMinutes);\n for(const key of ['workedMinutes','lateMinutes','earlyLeaveMinutes','overtimeMinutes'])if(adjustment&&adjustment[key]!==undefined)result[key]=Math.max(0,Number(adjustment[key]));\n return result;\n}\n\nfunction evaluateRule(rule,summary,context={}){\n let amount=0,type='deduction',reason=rule.name||rule.ruleType;\n const threshold=Number(rule.threshold??1),fixed=Number(rule.amount||0),formula=rule.formula||{};\n if(rule.ruleType==='late_fixed'&&summary.lateMinutes>=threshold){amount=fixed;reason=`تأخير ${summary.lateMinutes} دقيقة - ${context.workDate}`}\n if(rule.ruleType==='late_minutes'&&summary.lateMinutes>=threshold){amount=Math.floor(summary.lateMinutes/Number(formula.minutesPerUnit||threshold||1))*Number(formula.amountPerUnit||fixed);reason=`تأخير ${summary.lateMinutes} دقيقة - ${context.workDate}`}\n if(rule.ruleType==='absence_day'&&summary.absent){amount=fixed;reason=`غياب يوم - ${context.workDate}`}\n if(rule.ruleType==='early_leave'&&summary.earlyLeaveMinutes>=threshold){amount=fixed;reason=`خروج مبكر ${summary.earlyLeaveMinutes} دقيقة - ${context.workDate}`}\n if(rule.ruleType==='overtime_bonus'&&summary.overtimeMinutes>=threshold){amount=Math.floor(summary.overtimeMinutes/Number(formula.minutesPerUnit||threshold||1))*Number(formula.amountPerUnit||fixed);type='overtime';reason=`إضافي ${summary.overtimeMinutes} دقيقة - ${context.workDate}`}\n if(rule.ruleType==='attendance_bonus'&&!summary.absent&&!summary.incomplete&&summary.lateMinutes===0){amount=fixed;type='bonus';reason=`مكافأة انتظام - ${context.workDate}`}\n return amount>0?{type,amount:round2(amount),reason}:null;\n}\n\nfunction recurringPeriodKey(definition,dateValue){\n const d=new Date(`${dateValue}T00:00:00Z`),yyyy=d.getUTCFullYear(),mm=String(d.getUTCMonth()+1).padStart(2,'0');\n if(definition.frequency==='monthly')return `${yyyy}-${mm}`;\n if(definition.frequency==='weekly'){\n  const t=new Date(Date.UTC(yyyy,d.getUTCMonth(),d.getUTCDate()));t.setUTCDate(t.getUTCDate()+4-(t.getUTCDay()||7));\n  const y0=new Date(Date.UTC(t.getUTCFullYear(),0,1)),week=Math.ceil((((t-y0)/86400000)+1)/7);\n  return `${t.getUTCFullYear()}-W${String(week).padStart(2,'0')}`;\n }\n return dateValue;\n}\n\nfunction validatePayrollAttendanceCoverage({basis,requiredAttendanceDates=[],approvedLeaveDates=[],summaries=[]}){\n if(basis==='monthly')return {requiredDates:[],unresolvedDates:[]};\n const leave=new Set(approvedLeaveDates),byDate=new Map(summaries.map(row=>[row.workDate||row.work_date,row]));\n const required=[...new Set(requiredAttendanceDates)].filter(workDate=>!leave.has(workDate));\n const unresolved=required.filter(workDate=>{const row=byDate.get(workDate);return !row||String(row.verificationStatus||row.verification_status)!=='approved'});\n if(unresolved.length){const error=new Error(`ATTENDANCE_PERIOD_NOT_FINALIZED:${unresolved.join(',')}`);error.unresolvedDates=unresolved;throw error}\n return {requiredDates:required,unresolvedDates:[]};\n}\n\nfunction calculatePayroll({basis,rate,approvedSummaries=[],requiredAttendanceDates=[],approvedLeaveDates=[],adjustments=[],advanceDeduction=0}){\n validatePayrollAttendanceCoverage({basis,requiredAttendanceDates,approvedLeaveDates,summaries:approvedSummaries});\n const workedDays=approvedSummaries.filter(s=>s.verificationStatus==='approved'&&!s.absent&&Number(s.workedMinutes)>0).length;\n const workedMinutes=approvedSummaries.filter(s=>s.verificationStatus==='approved').reduce((n,s)=>n+Number(s.workedMinutes||0),0);\n const base=round2(basis==='monthly'?rate:basis==='daily'?rate*workedDays:rate*workedMinutes/60);\n const sum=type=>round2(adjustments.filter(a=>a.type===type).reduce((n,a)=>n+Number(a.amount||0),0));\n const bonus=sum('bonus'),overtime=sum('overtime'),deduction=Math.min(sum('deduction'),base+bonus+overtime);\n const advance=Math.min(Number(advanceDeduction||0),Math.max(0,base+bonus+overtime-deduction));\n return {basis,workedDays,workedMinutes,baseAmount:base,bonusAmount:bonus,overtimeAmount:overtime,deductionAmount:deduction,advanceDeduction:round2(advance),netAmount:round2(Math.max(0,base+bonus+overtime-deduction-advance))};\n}\n\nfunction payPayrollIdempotently(state,{clientTxId}){\n if(state.period.status==='paid')return {replay:true,treasuryMovements:state.treasuryMovements.length};\n if(state.period.status!=='approved')throw new Error('PAYROLL_NOT_APPROVED');\n for(const item of state.items){\n  const movementKey=`${clientTxId}:employee:${item.employeeId}`;\n  if(Number(item.netAmount)>0&&!state.treasuryMovements.some(row=>row.clientTxId===movementKey))state.treasuryMovements.push({clientTxId:movementKey,employeeId:item.employeeId,amount:Number(item.netAmount)});\n  let remaining=Number(item.advanceDeduction||0);\n  for(const advance of state.advances.filter(row=>row.employeeId===item.employeeId&&row.status==='active')){\n   if(remaining<=0)break;const amount=Math.min(Number(advance.outstandingAmount),remaining);advance.outstandingAmount=round2(Number(advance.outstandingAmount)-amount);remaining=round2(remaining-amount);if(advance.outstandingAmount<=0)advance.status='settled';\n  }\n }\n state.period.status='paid';state.period.paymentClientTxId=clientTxId;\n return {replay:false,treasuryMovements:state.treasuryMovements.length};\n}\n\nfunction buildPayslipLines(payroll,adjustments=[]){\n const lines=[{type:'basic_salary',amount:payroll.baseAmount,reason:'Basic Salary'}];\n if(payroll.basis==='daily')lines.push({type:'worked_days',amount:0,quantity:payroll.workedDays,reason:'Worked Days'});\n if(payroll.basis==='hourly')lines.push({type:'worked_hours',amount:0,quantity:round2(payroll.workedMinutes/60),reason:'Worked Hours'});\n for(const adjustment of adjustments)lines.push({type:adjustment.lineType||(adjustment.type==='bonus'?'bonus':adjustment.type==='overtime'?'overtime':'manual_deduction'),amount:Number(adjustment.amount),reason:adjustment.reason,effectiveDate:adjustment.effectiveDate});\n if(payroll.advanceDeduction>0)lines.push({type:'advance_installment',amount:payroll.advanceDeduction,reason:'Advance Installment'});\n lines.push({type:'net_salary',amount:payroll.netAmount,reason:'Net Salary'});return lines;\n}\n\nfunction validateCheckout(events,capturedAt){\n const at=new Date(capturedAt),accepted=events.filter(e=>validStatuses.has(e.verificationStatus)&&new Date(e.capturedAt)<=at&&new Date(e.capturedAt)>=new Date(at-36*3600000)).sort((a,b)=>new Date(a.capturedAt)-new Date(b.capturedAt));\n let open=false;for(const event of accepted){if(event.type==='check_in')open=true;if(event.type==='check_out')open=false}return open?{accepted:true}:{accepted:false,status:'rejected',reason:'missing_check_in'};\n}\n\nfunction authorizeStaffSelf({account,device,requestedEmployeeId,action}){\n const allowed=new Set(['self.read','attendance.submit','leave.create','pin.change','logout']);\n if(!account?.active)throw new Error('STAFF_ACCOUNT_DISABLED');\n if(!device?.active||device?.revoked)throw new Error('STAFF_DEVICE_REVOKED');\n if(Number(requestedEmployeeId)!==Number(account.employeeId))throw new Error('EMPLOYEE_SELF_SCOPE_VIOLATION');\n if(!allowed.has(action))throw new Error('STAFF_ADMIN_PRIVILEGE_FORBIDDEN');\n return true;\n}\n\nfunction branchScoped(rows,branchId){return rows.filter(row=>Number(row.branchId)===Number(branchId))}\n\nclass IdempotencyLedger{\n constructor(){this.rows=new Map()}\n submit(key,payload,create){\n  const digest=canonicalPayload(payload),old=this.rows.get(key);\n  if(old){if(old.digest!==digest)throw new Error('IDEMPOTENCY_PAYLOAD_MISMATCH');return {...old.value,replay:true}}\n  const value=create(payload);this.rows.set(key,{digest,value});return {...value,replay:false};\n }\n}\n\nclass MemoryQueueStore{\n constructor(seed=[]){this.rows=new Map(seed.map(x=>[x.clientTxId,structuredClone(x)]))}\n async list(){return [...this.rows.values()].map(row=>structuredClone(row))}\n async put(row){this.rows.set(row.clientTxId,structuredClone(row));return row}\n async remove(key){this.rows.delete(key)}\n}\n\nclass DurableAttendanceQueue{\n constructor(store){this.store=store;this.running=false}\n async enqueue(envelope){\n  if(!envelope.clientTxId||!envelope.selfie)throw new Error('INVALID_OFFLINE_ENVELOPE');\n  const rows=await this.store.list(),old=rows.find(x=>x.clientTxId===envelope.clientTxId),digest=canonicalPayload({...envelope,selfie:{size:envelope.selfie.size,type:envelope.selfie.type}});\n  if(old&&old.digest!==digest)throw new Error('OFFLINE_TX_PAYLOAD_MISMATCH');\n  if(old)return old;\n  const row={...envelope,digest,state:'pending',attempts:0,createdAt:new Date().toISOString()};await this.store.put(row);return row;\n }\n async pending(){return (await this.store.list()).filter(x=>x.state!=='acked')}\n async replay(send){\n  if(this.running)return {skipped:true,synced:0};this.running=true;let synced=0;\n  try{\n   for(const row of await this.pending()){\n    row.state='syncing';row.attempts+=1;await this.store.put(row);\n    try{const ack=await send(row);row.state='acked';row.ack=ack;await this.store.put(row);await this.store.remove(row.clientTxId);synced++}\n    catch(error){row.state='pending';row.lastError=String(error?.message||error);await this.store.put(row);break}\n   }\n   return {skipped:false,synced};\n  }finally{this.running=false}\n }\n}\n\nreturn {canonicalPayload,haversineMeters,verifyGeofence,calculateDailySummary,evaluateRule,recurringPeriodKey,validatePayrollAttendanceCoverage,calculatePayroll,payPayrollIdempotently,buildPayslipLines,validateCheckout,authorizeStaffSelf,branchScoped,IdempotencyLedger,MemoryQueueStore,DurableAttendanceQueue};\n});\n"},"hr-staff-store.js":{"type":"text/javascript; charset=utf-8","body":"(function(global){\n'use strict';\nconst DB_NAME='sharawla-staff-v1',DB_VERSION=1,QUEUE='attendance_queue';\nlet dbPromise=null;\nfunction open(){\n if(dbPromise)return dbPromise;\n dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,DB_VERSION);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(QUEUE)){const store=db.createObjectStore(QUEUE,{keyPath:'clientTxId'});store.createIndex('state','state')}};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});\n return dbPromise;\n}\nasync function transaction(mode,fn){const db=await open();return new Promise((resolve,reject)=>{const tx=db.transaction(QUEUE,mode),store=tx.objectStore(QUEUE);let result;try{result=fn(store)}catch(e){reject(e);return}tx.oncomplete=()=>resolve(result?.result??result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('INDEXEDDB_ABORTED'))})}\nconst queueStore={\n list:()=>transaction('readonly',s=>s.getAll()),\n put:row=>transaction('readwrite',s=>s.put(row)),\n remove:key=>transaction('readwrite',s=>s.delete(key)),\n};\nfunction randomId(){if(crypto.randomUUID)return crypto.randomUUID();const b=new Uint8Array(16);crypto.getRandomValues(b);return [...b].map(v=>v.toString(16).padStart(2,'0')).join('')}\nfunction deviceId(){let id=localStorage.getItem('sharawlaStaffDeviceIdV1');if(!id){id=randomId();localStorage.setItem('sharawlaStaffDeviceIdV1',id)}return id}\nfunction config(){try{return JSON.parse(localStorage.getItem('sharawlaStaffConfigV1')||'null')}catch{return null}}\nfunction saveConfig(value){localStorage.setItem('sharawlaStaffConfigV1',JSON.stringify(value))}\nfunction session(){try{return JSON.parse(localStorage.getItem('sharawlaStaffSessionV1')||'null')}catch{return null}}\nfunction saveSession(value){if(value)localStorage.setItem('sharawlaStaffSessionV1',JSON.stringify(value));else localStorage.removeItem('sharawlaStaffSessionV1')}\nglobal.SharawlaStaffStore=Object.freeze({queueStore,deviceId,config,saveConfig,session,saveSession,randomId});\n})(globalThis);\n"},"styles.css":{"type":"text/css; charset=utf-8","body":":root{font-family:system-ui,-apple-system,\"Segoe UI\",Tahoma,sans-serif;color:#17211f;background:#f4f7f5;--green:#0b3b35;--gold:#e9b949;--card:#fff;--muted:#6a7773;--danger:#b3261e}*{box-sizing:border-box}body{margin:0;min-height:100dvh;background:linear-gradient(160deg,#eef6f2,#f7f4ea)}button,input,textarea,select{font:inherit}button{cursor:pointer}.hidden{display:none!important}#toast{position:fixed;z-index:100;top:calc(14px + env(safe-area-inset-top));left:50%;transform:translate(-50%,-20px);max-width:92vw;padding:11px 16px;border-radius:999px;background:#102d29;color:#fff;opacity:0;pointer-events:none;transition:.2s}#toast.show{opacity:1;transform:translate(-50%,0)}#shell{min-height:100dvh;padding-bottom:82px}.topbar{position:sticky;top:0;z-index:10;display:flex;justify-content:space-between;align-items:center;padding:calc(10px + env(safe-area-inset-top)) 16px 10px;background:rgba(11,59,53,.97);color:#fff;box-shadow:0 2px 14px #0002}.brand{display:flex;align-items:center;gap:9px}.brand img{width:42px;height:42px}.brand strong,.brand small{display:block}.brand small{opacity:.76}.status{font-size:.82rem;display:flex;align-items:center;gap:6px}.status span:first-child{width:9px;height:9px;border-radius:50%;background:#55d68b}.status.offline span:first-child{background:#ff8a80}.view{min-height:calc(100dvh - 64px)}.auth-view{display:grid;place-items:center;padding:24px 16px}.auth-card{width:min(100%,420px);background:#fff;border-radius:24px;padding:24px;box-shadow:0 18px 55px #1232}.hero-icon{display:block;width:96px;margin:0 auto 12px}.auth-card h1{margin:0 0 8px;color:var(--green)}.auth-card p{color:var(--muted);line-height:1.6}label{display:grid;gap:6px;margin:14px 0;font-weight:700}input,textarea,select{width:100%;border:1px solid #cbd7d2;border-radius:12px;padding:13px;background:#fff;color:#17211f}.primary{border:0;border-radius:13px;background:var(--green);color:#fff;padding:13px 18px;font-weight:800}.auth-card .primary{width:100%;margin-top:8px}.link-btn{border:0;background:none;color:var(--green);width:100%;margin-top:18px}.page{padding:18px 16px;max-width:760px;margin:auto}.offline-banner{background:#fff0c2;color:#6f4f00;padding:9px 16px;text-align:center;font-weight:700}.hero-card,.card{background:var(--card);border:1px solid #dfe9e5;border-radius:20px;padding:18px;box-shadow:0 8px 28px #1231;margin-bottom:14px}.hero-card{background:linear-gradient(145deg,var(--green),#14695f);color:#fff}.hero-card h1{margin:0 0 4px}.muted{color:var(--muted)}.hero-card .muted{color:#d5e9e5}.clock{font-size:2.35rem;font-weight:900;margin:18px 0}.attendance-actions{display:grid;grid-template-columns:1fr 1fr;gap:12px}.attendance-actions button{border:0;border-radius:17px;padding:18px 8px;font-weight:900}.check-in{background:var(--gold);color:#2e250b}.check-out{background:#fff;color:var(--green)}.kpi-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.kpi{background:#fff;border:1px solid #dfe9e5;border-radius:16px;padding:13px}.kpi b{display:block;font-size:1.45rem;color:var(--green)}.row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #edf1ef}.row small{display:block}.row:last-child{border:0}.pill{display:inline-block;border-radius:999px;padding:4px 9px;background:#e8f2ee;color:var(--green);font-size:.82rem}.pill.warn{background:#fff0c2;color:#6f4f00}.pill.bad{background:#ffe3e0;color:var(--danger)}.bottom-nav{position:fixed;bottom:0;left:0;right:0;z-index:12;display:grid;grid-template-columns:repeat(5,1fr);padding:8px 6px calc(8px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid #dce6e2;box-shadow:0 -5px 25px #1232}.bottom-nav button{position:relative;border:0;background:none;color:#61706b;font-size:.7rem;padding:4px}.bottom-nav button span{display:block;font-size:1.35rem}.bottom-nav button.active{color:var(--green);font-weight:800}.badge{position:absolute;top:0;left:calc(50% - 20px);background:var(--danger);color:#fff;border-radius:99px;min-width:18px;padding:1px 5px}.camera-modal{position:fixed;inset:0;z-index:50;background:#061e1beF;display:grid;align-items:end}.camera-card{background:#fff;border-radius:25px 25px 0 0;padding:18px 16px calc(18px + env(safe-area-inset-bottom));max-height:95dvh;overflow:auto}.camera-card h2{margin:0}.camera-card video{display:block;width:100%;max-height:55dvh;object-fit:cover;border-radius:18px;background:#111;transform:scaleX(-1);margin:12px 0}.camera-actions{display:grid;grid-template-columns:1fr 2fr;gap:10px}.camera-actions button{border:1px solid #cad7d2;border-radius:13px;padding:13px}.gps-state{padding:10px;border-radius:12px;background:#eef4f2;margin-bottom:12px}.sync-item{border-inline-start:4px solid var(--gold);padding-inline-start:12px}.danger{color:var(--danger)}@media(min-width:720px){.kpi-grid{grid-template-columns:repeat(4,1fr)}.camera-modal{align-items:center;justify-items:center}.camera-card{width:min(600px,94vw);border-radius:25px;padding:22px}}\n\n.staff-request-actions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}\n.staff-request-actions button,.section-title button{border:1px solid #cad7d2;border-radius:13px;padding:11px 13px;background:#fff;color:var(--green);font-weight:800}\n.section-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:8px}.section-title h3{margin:0}\n.self-note{width:100%;display:block;text-align:right;border:1px solid #dfe9e5;background:#fff;border-radius:14px;padding:12px;margin:8px 0;color:#17211f}\n.self-note.unread{border-color:#1b7f72;background:#effaf7}.self-note b,.self-note span,.self-note small{display:block}.self-note span{margin-top:4px}.self-note small{color:var(--muted);margin-top:5px}\n@media(max-width:440px){.staff-request-actions{grid-template-columns:1fr}}\n"},"sw.js":{"type":"text/javascript; charset=utf-8","body":"'use strict';\nconst CACHE='sharawla-staff-v10.5.14-hr2';\nconst ASSETS=['./','./index.html','./styles.css','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest','./hr-staff-domain.js','./hr-staff-store.js','./app.js'];\nself.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting())));\nself.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('sharawla-staff-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));\nself.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;const url=new URL(event.request.url);if(url.origin!==location.origin)return;event.respondWith(fetch(event.request).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));return response}).catch(()=>caches.match(event.request).then(response=>response||caches.match('./index.html'))))});\nself.addEventListener('sync',event=>{if(event.tag==='sharawla-staff-replay')event.waitUntil(self.clients.matchAll({type:'window',includeUncontrolled:true}).then(clients=>clients.forEach(client=>client.postMessage({type:'REPLAY_PENDING'}))))});\n"},"manifest.webmanifest":{"type":"application/manifest+json; charset=utf-8","body":"{\n  \"id\": \"/staff/\",\n  \"name\": \"Sharawla Staff\",\n  \"short_name\": \"Staff\",\n  \"description\": \"Sharawla employee attendance and self service\",\n  \"lang\": \"ar\",\n  \"dir\": \"rtl\",\n  \"start_url\": \"./?source=pwa\",\n  \"scope\": \"./\",\n  \"display\": \"standalone\",\n  \"orientation\": \"portrait-primary\",\n  \"background_color\": \"#f4f7f5\",\n  \"theme_color\": \"#0b3b35\",\n  \"icons\": [\n    {\"src\":\"icon-192.png\",\"sizes\":\"192x192\",\"type\":\"image/png\",\"purpose\":\"any\"},\n    {\"src\":\"icon-512.png\",\"sizes\":\"512x512\",\"type\":\"image/png\",\"purpose\":\"any\"},\n    {\"src\":\"icon.svg\",\"sizes\":\"any\",\"type\":\"image/svg+xml\",\"purpose\":\"any maskable\"}\n  ]\n}\n"},"icon.svg":{"type":"image/svg+xml; charset=utf-8","body":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 512 512\">\n <rect width=\"512\" height=\"512\" rx=\"112\" fill=\"#0b3b35\"/>\n <circle cx=\"256\" cy=\"188\" r=\"88\" fill=\"#e9b949\"/>\n <path d=\"M100 438c12-103 69-154 156-154s144 51 156 154\" fill=\"#f4f7f5\"/>\n <path d=\"M164 72h184v54H164z\" rx=\"16\" fill=\"#f4f7f5\"/>\n <text x=\"256\" y=\"493\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" font-size=\"42\" font-weight=\"700\" fill=\"#e9b949\">STAFF</text>\n</svg>\n"}};
