function bytesFromBase64(value:string){
 const raw=atob(value);const out=new Uint8Array(raw.length);
 for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);
 return out;
}
function pathFor(req:Request){
 const p=new URL(req.url).pathname;
 const marker="/functions/v1/hr-staff-app";
 const i=p.indexOf(marker);
 let rest=i>=0?p.slice(i+marker.length):"/";
 if(!rest||rest==="/")return "index.html";
 rest=rest.replace(/^\/+/, "");
 return rest.split("?")[0]||"index.html";
}
function headers(type:string,name:string){
 return {
  "content-type":type,
  "cache-control":name==="index.html"||name==="sw.js"||name==="manifest.webmanifest"?"no-store":"public, max-age=3600",
  "x-content-type-options":"nosniff"
 };
}
Deno.serve((req:Request)=>{
 if(req.method!=="GET"&&req.method!=="HEAD")return new Response("Method Not Allowed",{status:405});
 const name=pathFor(req);
 if(name==="index.html"){
  let html=TEXT_ASSETS["index.html"].body;
  const config=`<script>window.SHARAWLA_STAFF_CONFIG={url:${JSON.stringify(PROJECT_URL)},key:${JSON.stringify(PUBLISHABLE_KEY)}};<\/script>`;
  html=html.replace('<script src="hr-staff-domain.js?v=10.5.14"></script>',config+'\n <script src="hr-staff-domain.js?v=10.5.14"></script>');
  return new Response(req.method==="HEAD"?null:html,{status:200,headers:headers("text/html; charset=utf-8",name)});
 }
 if(name==="manifest.webmanifest"){
  const manifest=JSON.parse(TEXT_ASSETS[name].body);
  manifest.id="./";manifest.start_url="./?source=pwa";manifest.scope="./";
  return new Response(req.method==="HEAD"?null:JSON.stringify(manifest),{status:200,headers:headers(TEXT_ASSETS[name].type,name)});
 }
 const t=TEXT_ASSETS[name];
 if(t)return new Response(req.method==="HEAD"?null:t.body,{status:200,headers:headers(t.type,name)});
 const p=PNG_ASSETS[name];
 if(p)return new Response(req.method==="HEAD"?null:bytesFromBase64(p),{status:200,headers:headers("image/png",name)});
 return new Response("Not Found",{status:404,headers:{"content-type":"text/plain; charset=utf-8","cache-control":"no-store"}});
});
